# fetch inbox threads for cancel-related query

def fetch_inbox_threads(query):
    all_threads=[]
    page=0
    while True:
        resp = apis.gmail.show_inbox_threads(access_token=token_gmail, query=query, page_index=page, page_limit=20)
        threads = resp['email_threads'] if isinstance(resp, dict) and 'email_threads' in resp else resp
        if not threads:
            break
        all_threads.extend(threads)
        page += 1
    return all_threads

threads = fetch_inbox_threads('Cancel Meeting')
print('total threads for query Cancel Meeting:', len(threads))

# filter by subject pattern and by sender not Jamie (sender approximated by participants[0])
jamie='jamie-solomon@gmail.com'

def sender_email(t):
    parts=t.get('participants',[])
    if not parts: return None
    return parts[0].get('email')

def sender_name(t):
    parts=t.get('participants',[])
    if not parts: return None
    return parts[0].get('name')

